arguments.argument:
with(obj_unit)
{
    if global.player_com[player]
    {
        if unit_s>0 and !moni_go and drag_ok=1
        {
            if attack_waits=1
            {
                attack_unit=in_bbox_data_find(1, x, y, id, 99999)
                if !instance_number(attack_unit)
                {
                    attack_unit=in_point_data_find(4, x, y, id, 99999)
                    if instance_number(attack_unit)
                    {
                        attack_waits=4
                    }
                }
                else
                {
                    attack_waits=4
                }
            }
        }
    }
}

alarm[3]=room_speed*400/global.player_com_ai
